  function arr(v){return Array.isArray(v)?v:[];}
  function num(v){const n=Number(v);return Number.isFinite(n)?n:0;}
  function day(value){if(!value)return null;const s=String(value).slice(0,10);if(!/^\d{4}-\d{2}-\d{2}$/.test(s))return null;const d=new Date(s+'T00:00:00Z');return Number.isNaN(d.getTime())?null:d;}
