  function todayValue(options){return iso(options&&options.today)||new Date().toISOString().slice(0,10);}
  function supplier(name){const d=getData()||{};return arr(d.suppliers).find(s=>s&&s.name===name)||null;}
  function product(id){const d=getData()||{};return arr(d.products).find(p=>p&&p.id===id)||null;}
  function supplierPos(name){const d=getData()||{};return arr(d.purchaseOrders).filter(po=>po&&po.supplier===name);}
  function lineCost(line){const p=product(line&&line.productId)||{};return num(line&&line.confirmedUnitCost!=null?line.confirmedUnitCost:line&&line.unitCost!=null?line.unitCost:p.cost);}
  function poOrderedValue(po){return arr(po&&po.lines).reduce((sum,line)=>sum+num(line.qty)*lineCost(line),0);}
  function poOutstandingValue(po){return arr(po&&po.lines).reduce((sum,line)=>sum+Math.max(0,num(line.qty)-num(line.received))*lineCost(line),0);}
  function poSummary(po){return arr(po&&po.lines).reduce((r,line)=>{r.ordered+=num(line.qty);r.received+=num(line.received);r.outstanding+=Math.max(0,num(line.qty)-num(line.received));return r;},{ordered:0,received:0,outstanding:0});}
  function orderedDate(po){const lineDate=arr(po&&po.lines).map(l=>iso(l.orderedDate)).filter(Boolean).sort()[0];return iso(po&&po.orderedDate)||iso(po&&po.createdAt)||lineDate||'';}
  function promisedDate(po){const dates=arr(po&&po.lines).map(l=>iso(l.confirmedEta||l.dueDate)).filter(Boolean).sort();return dates.length?dates[dates.length-1]:iso(po&&po.confirmedEta)||iso(po&&po.due)||'';}
  function actualReceiptDate(po){const d=getData()||{};const dates=arr(d.receiptEvents).filter(e=>e&&e.poId===po.id&&!e.legacy&&e.date).map(e=>iso(e.date)).filter(Boolean).sort();return dates.length?dates[dates.length-1]:iso(po&&po.receivedAt)||iso(po&&po.receivedDate)||'';}
