  function billRows(name,options){const today=todayValue(options);const docs=financeDocsForSupplier(name);const pos=supplierPos(name);if(docs.length)return docs.map(doc=>{const po=pos.find(p=>p.id===doc.source_id)||{};const due=iso(po.supplierInvoiceDueDate||po.invoiceDueDate||doc.due_date||doc.dueDate);const amountDue=Math.max(0,num(doc.amount_due));const overdue=amountDue>0&&due&&due<today;return {id:doc.xero_number||doc.id,poId:doc.source_id,status:doc.status||'Linked',amountDue,amountPaid:num(doc.amount_paid),amountCredited:num(doc.amount_credited),dueDate:due,overdue,source:'Xero'};});return pos.filter(po=>po.supplierInvoiceRef||num(po.supplierInvoiceTotal)).map(po=>{const amountDue=localPayable(po);const due=iso(po.supplierInvoiceDueDate||po.invoiceDueDate);return {id:po.supplierInvoiceRef||('Invoice for '+po.id),poId:po.id,status:po.supplierPaymentStatus||(amountDue?'Outstanding':'Paid'),amountDue,amountPaid:num(po.supplierPaidAmount||po.supplierInvoicePaidAmount),amountCredited:num(po.supplierCreditApplied),dueDate:due,overdue:amountDue>0&&due&&due<today,source:'PO'};});}
  function smartFlags(name,options){const d=getData()||{},today=todayValue(options),flags=[],credit=creditPosition(name);if(['watch','warning','critical'].includes(credit.severity))flags.push({type:'credit-warning',severity:credit.severity,title:credit.severity==='critical'?'Projected credit limit exceeded':'Credit limit getting close',detail:'Projected exposure '+credit.projectedPercent+'% of supplier limit.',tab:'Overview',action:'Review credit'});
    supplierPos(name).forEach(po=>{const sum=poSummary(po),timing=poTiming(po,{today});if(timing.state==='late'&&sum.outstanding>0)flags.push({type:'late-po',severity:'critical',title:po.id+' is '+timing.label.toLowerCase(),detail:sum.outstanding+' unit(s) still outstanding.',tab:'Late & Backorders',poId:po.id,action:'Open PO'});if(sum.received>0&&sum.outstanding>0)flags.push({type:'short-receipt',severity:'warning',title:po.id+' received short',detail:sum.received+' of '+sum.ordered+' received, '+sum.outstanding+' outstanding.',tab:'Late & Backorders',poId:po.id,action:'Chase supplier'});arr(po.lines).forEach(line=>{if(Math.max(0,num(line.qty)-num(line.received))>0&&iso(line.nextChaseDate)&&iso(line.nextChaseDate)<=today&&String(line.chaseStatus||'').toLowerCase()!=='confirmed')flags.push({type:'chase-due',severity:'warning',title:'Supplier chase due for '+po.id,detail:(product(line.productId)||{}).sku||line.productId,tab:'Late & Backorders',poId:po.id,productId:line.productId,action:'Record chase'});});if(isFullyReceived(po)){const financeLinked=financeDocsForSupplier(name).some(doc=>doc.source_id===po.id);if(!po.supplierInvoiceRef&&!num(po.supplierInvoiceTotal)&&!financeLinked)flags.push({type:'invoice-missing',severity:'warning',title:'Supplier invoice missing for '+po.id,detail:'Goods fully received but no supplier invoice is linked.',tab:'Bills & Credits',poId:po.id,action:'Record invoice'});}if((po.supplierInvoiceRef||num(po.supplierInvoiceTotal))&&!['Matched','Approved variance'].includes(po.invoiceMatchStatus||''))flags.push({type:'invoice-match',severity:'warning',title:'Invoice match required for '+po.id,detail:'Compare PO, Goods-In and supplier invoice before payment.',tab:'Bills & Credits',poId:po.id,action:'Review match'});});
    billRows(name,{today}).forEach(b=>{if(b.overdue)flags.push({type:'payment-overdue',severity:'critical',title:(b.id||b.poId)+' overdue and unpaid',detail:'Outstanding '+b.amountDue.toFixed(2)+(b.dueDate?' · due '+b.dueDate:''),tab:'Bills & Credits',poId:b.poId,billId:b.id,action:'Open bill'});});
    arr(d.purchaseReturns).filter(r=>r&&r.supplier===name&&!['Closed','Credited','Cancelled'].includes(r.status)&&num(r.expectedCredit)>0).forEach(r=>flags.push({type:'supplier-credit',severity:'warning',title:'Supplier credit outstanding · '+r.id,detail:'Expected credit '+num(r.expectedCredit).toFixed(2)+'.',tab:'Returns & Credits',returnId:r.id,action:'Chase credit'}));
    const pending=(supplier(name)||{}).pendingPriceListReview; if(pending&&arr(pending.rows).length){const ps=pending.summary||{};flags.push({type:'cost-change',severity:(num(ps.increased)>0||num(ps.unmatched)>0)?'warning':'info',title:'Supplier price list needs review',detail:num(ps.increased)+' increase(s), '+num(ps.decreased)+' decrease(s), '+num(ps.unmatched)+' unmatched.',tab:'Products & Price Lists',action:'Review costs'});}
    const weight={critical:0,warning:1,watch:2,info:3};return flags.sort((a,b)=>(weight[a.severity]??9)-(weight[b.severity]??9)||a.title.localeCompare(b.title));}
  function stockForProduct(id){const d=getData()||{};return arr(d.stock).filter(r=>r&&r.productId===id).reduce((sum,r)=>sum+num(r.qty),0);}
  function inboundForProduct(id,name){return supplierPos(name).reduce((sum,po)=>sum+arr(po.lines).filter(l=>l.productId===id).reduce((x,l)=>x+Math.max(0,num(l.qty)-num(l.received)),0),0);}
  function productRows(name){const d=getData()||{},offers=arr(d.supplierProducts).filter(o=>o&&o.supplier===name),rows=[],seen=new Set();offers.forEach(offer=>{const p=product(offer.productId);if(!p)return;seen.add(p.id);rows.push({offerId:offer.id||'',productId:p.id,sku:p.sku||'',supplierSku:offer.supplierSku||p.supplierSku||'',name:p.name||'',cost:num(offer.cost!=null?offer.cost:p.cost),rrp:num(p.rrp),leadTimeDays:num(offer.leadTimeDays||(supplier(name)||{}).leadTimeDays),preferred:Boolean(offer.preferred||p.preferredSupplier===name||p.supplier===name),available:offer.available!==false,status:offer.available===false?'Discontinued':'Active',stock:stockForProduct(p.id),onPo:inboundForProduct(p.id,name),missingSupplierSku:!(offer.supplierSku||p.supplierSku)});});arr(d.products).filter(p=>p&&p.supplier===name&&!seen.has(p.id)).forEach(p=>rows.push({offerId:'',productId:p.id,sku:p.sku||'',supplierSku:p.supplierSku||'',name:p.name||'',cost:num(p.cost),rrp:num(p.rrp),leadTimeDays:num((supplier(name)||{}).leadTimeDays),preferred:true,available:true,status:'Active',stock:stockForProduct(p.id),onPo:inboundForProduct(p.id,name),missingSupplierSku:!p.supplierSku}));return rows.sort((a,b)=>a.name.localeCompare(b.name));}
  function parseCsv(text){const lines=String(text||'').replace(/^\uFEFF/,'').split(/\r?\n/).filter(line=>line.trim());if(lines.length<2)return {headers:[],rows:[]};function split(line){const out=[];let cur='',quote=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'){if(quote&&line[i+1]==='"'){cur+='"';i++;}else quote=!quote;}else if(c===','&&!quote){out.push(cur.trim());cur='';}else cur+=c;}out.push(cur.trim());return out;}const headers=split(lines[0]).map(h=>h.toLowerCase().replace(/[^a-z0-9]+/g,''));return {headers,rows:lines.slice(1).map(split)};}
