  function previewPriceList(name,text){const parsed=parseCsv(text),skuI=findHeader(parsed.headers,['suppliersku','vendorsku','suppliercode']),poolI=findHeader(parsed.headers,['poolshedsku','sku','productsku']),costI=findHeader(parsed.headers,['netcost','cost','unitcost','buyprice']),leadI=findHeader(parsed.headers,['leadtime','leadtimedays']),statusI=findHeader(parsed.headers,['status','availability']);const current=productRows(name);const rows=parsed.rows.map((cols,index)=>{const supplierSku=skuI>=0?cols[skuI]||'':'';const poolSku=poolI>=0?cols[poolI]||'':'';const match=current.find(r=>(supplierSku&&r.supplierSku.toLowerCase()===supplierSku.toLowerCase())||(poolSku&&r.sku.toLowerCase()===poolSku.toLowerCase()));const newCost=costI>=0?num(cols[costI]):0,oldCost=match?num(match.cost):0;let change='unmatched';if(match){if(newCost>oldCost+0.0001)change='increased';else if(newCost<oldCost-0.0001)change='decreased';else change='unchanged';}return {id:'PRICE-'+(index+1),supplier:name,productId:match?match.productId:'',offerId:match?match.offerId:'',supplierSku:supplierSku||match&&match.supplierSku||'',poolSku:poolSku||match&&match.sku||'',productName:match?match.name:'Unmatched supplier product',oldCost,newCost,leadTimeDays:leadI>=0?num(cols[leadI]):match?match.leadTimeDays:0,status:statusI>=0?(cols[statusI]||'Active'):'Active',change,matched:Boolean(match)};});const summary={increased:0,decreased:0,unchanged:0,unmatched:0};rows.forEach(r=>summary[r.change]++);return {supplier:name,createdAt:new Date().toISOString(),rows,summary};}
